characters={c['id']:c for c in project['script']['characters']}
queue=[]
for panel in project['script']['panels']:
    pid=panel['id'];binding={'appearance_versions':panel['appearance_versions'],'reference_ids':[refs[s] for s in selection[pid]]}
    bind_path=root/'design/panel-bindings'/(pid+'.json');cp.atomic_json(bind_path,binding)
    cp.run(cp.parser().parse_args(['bind-panel','--project',str(root),'--panel',pid,'--bindings',str(bind_path)]))
