    roles=[]
    for index,(stem,reference) in enumerate(zip(selection[pid],selected),1):
        roles.append(f'Image {index} ({stem}) = '+json.dumps(reference['subjects'],ensure_ascii=False))
    if pid!='p16':roles.append(f'Image {len(image_paths)} = workshop layout and props ONLY; do not output its model-sheet insets. Missing ring/box contents determined by this action, not generic reference state.')
    prompt=('Use case: illustration-story. Output ONE single continuous full-color story comic PANEL, landscape 3:2 canvas, NOT a model sheet, montage, grid or page. Same precise refined illustrated manga style, subtle clean contours, softly shaded warm ivory/sea-gray colors as these validated reference images; not photo.\n'
            +'Reference roles:\n'+'\n'.join(roles)+'\n'
            +'Action and framing (one simultaneous instant): '+action[pid]+'\n'
            +'Identity constraints for ONLY these present people: '+json.dumps({cid:{'name':characters[cid]['name'],'gender':characters[cid]['appearance']['gender_presentation'],'identity_card':characters[cid]['identity_card'],'version':panel['appearance_versions'][cid]} for cid in panel['cast']},ensure_ascii=False)+'\n'
            +'Keep exact individual faces, body silhouettes, age, gender presentation and costume versions. Women unmistakably feminine faces/shoulders/body, men unmistakably masculine bone structure/shoulders. Leads remain finely designed and refined, background people natural and properly drawn. Correct hands/arms, no merged people or cloned faces. Paper/envelope blank and unlettered. No dialogue, captions, speech bubbles, labels, characters, signage, watermark, page borders or inset portraits. Fill one continuous narrative scene; final dialogue will be typeset separately. Do not imitate reference-sheet layout. Important faces/actions comfortably within canvas, no critical clipping.')
    prompt_path=root/'prompts/production'/(pid+'-a1.txt');prompt_path.parent.mkdir(parents=True,exist_ok=True);prompt_path.write_text(prompt,encoding='utf-8')
